-- referenced anywhere in this file and is left exactly as it is.
-- ============================================================================

begin;

-- Clear any previous seed so re-running gives a clean, coherent picture rather
-- than mixing this run with an earlier one. Rows from other runs are untouched.
delete from public.incident_clusters_v2 where run_id = 'RUN-SCALE-0001';
delete from public.safety_escalations   where run_id = 'RUN-SCALE-0001';

-- ---- the alerts these incidents were derived from -----------------------
-- Added alongside whatever raw_alerts already holds. Every id here starts
-- with 'ALT-1', so the originals (ALT-001..ALT-025) cannot collide
-- with them and `where id like 'ALT-1%'` removes exactly this batch.
on conflict ("id") do update set "timestamp" = excluded."timestamp", "source" = excluded."source", "type" = excluded."type", "location" = excluded."location", "severity" = excluded."severity", "message" = excluded."message";


-- ---- the Stage 1 run this data came from --------------------------------
on conflict ("run_id") do update set "config" = excluded."config", "stats" = excluded."stats", "noise_alert_ids" = excluded."noise_alert_ids";


-- ---- incidents ----------------------------------------------------------
on conflict ("cluster_id") do update set "name" = excluded."name", "primary_location" = excluded."primary_location", "assigned_agent" = excluded."assigned_agent", "raw_alert_ids" = excluded."raw_alert_ids", "run_id" = excluded."run_id", "schema_version" = excluded."schema_version", "problem_type" = excluded."problem_type", "problem_type_label" = excluded."problem_type_label", "is_singleton" = excluded."is_singleton", "assigned_domain" = excluded."assigned_domain", "created_at" = excluded."created_at", "nearest_named_feature" = excluded."nearest_named_feature", "coordinates" = excluded."coordinates", "suggested_priority" = excluded."suggested_priority", "clustering_metadata" = excluded."clustering_metadata", "participating_vehicles" = excluded."participating_vehicles", "evidence_refs" = excluded."evidence_refs", "incident_metadata" = excluded."incident_metadata";


-- ---- safety-channel escalations -----------------------------------------
on conflict ("escalation_id") do update set "run_id" = excluded."run_id", "schema_version" = excluded."schema_version", "route" = excluded."route", "escalation_tier" = excluded."escalation_tier", "raised_at" = excluded."raised_at", "source_alert_id" = excluded."source_alert_id", "vehicle_id" = excluded."vehicle_id", "error_code" = excluded."error_code", "eci_event" = excluded."eci_event", "location" = excluded."location", "last_state" = excluded."last_state", "evidence_refs" = excluded."evidence_refs";

commit;

